<?php

namespace App\Support\Reports;

use App\Domain\Reports\ChedReport;
use RuntimeException;
use ZipArchive;

/**
 * Writes the owner's CHED / NSTP templates (`resources/ched-templates`) filled with report rows
 * (ADR 0049). The template package is copied and only its worksheet is rewritten, so the layout,
 * merged cells, print setup and the CHED logo stay exactly as CHED sent them.
 *
 * What it does to the worksheet:
 *  - the data rows are generated by cloning the template's own first data row (same cell styles),
 *    as many as there are students (a list longer than the template simply gets more rows);
 *  - NSTP forms: the footer (sub total, grand total, signatures) moves down below the last row,
 *    its merged cells move with it, and its COUNTIF ranges and cached counts follow the rows;
 *  - text is written as inline strings (no shared-string table to keep in step);
 *  - `calcChain.xml` is dropped and the workbook is told to recalculate on open, so Excel rebuilds
 *    its formula chain itself.
 * It uses `ZipArchive` only: no spreadsheet library is a dependency (the local PHP has no `gd`).
 */
final class ChedWorkbookWriter
{
    private const TEMPLATES = [
        'enrollment-list' => 'ched-enrollment-list.xlsx',
        'nstp-enrollment' => 'nstp-form-2b-enrollment.xlsx',
        'nstp-graduates' => 'nstp-form-2b-graduates.xlsx',
        'nstp-summary' => 'nstp-form-2a-summary.xlsx',
    ];

    private const SHEET = 'xl/worksheets/sheet1.xml';

    private const ROW = '#<row\b[^>]*?/>|<row\b[^>]*?>.*?</row>#s';

    private const CELL = '#<c\b([^>]*?)(?:/>|>(.*?)</c>)#s';

    /** Form 2-A: the order of the three NSTP components, two columns (M, F) each, from column C. */
    private const COMPONENTS = ['rotc', 'cwts', 'lts'];

    public function __construct(private readonly ?string $templateDirectory = null) {}

    /**
     * @param  list<array<string, int|string>>  $rows
     */
    public function writeList(ChedReport $report, array $rows, ChedReportHeader $header, string $path): void
    {
        $zip = $this->openCopyOf($report, $path);
        $sheet = $this->sheetOf($zip);

        $sheet = $report === ChedReport::EnrollmentList
            ? $this->fillEnrollmentList($sheet, $rows, $header)
            : $this->fillNstpList($sheet, $rows, $header);

        $this->save($zip, $sheet);
    }

    /**
     * @param  array{
     *     campus: string, classification: string, academic_year: string,
     *     enrollment: array<string, array<string, array{m: int, f: int}>>,
     *     graduates: array<string, array{m: int, f: int}>,
     * }  $summary
     */
    public function writeSummary(array $summary, string $path): void
    {
        $zip = $this->openCopyOf(ChedReport::NstpSummary, $path);
        $sheet = $this->sheetOf($zip);

        $sheet = $this->setText($sheet, 'A7', 'Academic Year: '.$summary['academic_year']);
        $sheet = $this->setText($sheet, 'A15', $summary['campus']);
        $sheet = $this->setText($sheet, 'B15', $summary['classification']);
        $sheet = $this->setNumber($sheet, 'B30', 1, keepFormula: true);

        // Columns C..Z: 1st Sem, 2nd Sem, Summer (enrollment), then Graduates; ROTC, CWTS, LTS; M, F.
        $groups = [
            $summary['enrollment']['1st'],
            $summary['enrollment']['2nd'],
            $summary['enrollment']['summer'],
            $summary['graduates'],
        ];
        $column = 3;
        foreach ($groups as $group) {
            foreach (self::COMPONENTS as $component) {
                foreach (['m', 'f'] as $gender) {
                    $letter = $this->columnLetter($column++);
                    $value = (int) $group[$component][$gender];
                    $sheet = $this->setNumber($sheet, $letter.'15', $value);
                    $sheet = $this->setNumber($sheet, $letter.'30', $value, keepFormula: true);
                }
            }
        }

        $this->save($zip, $sheet);
    }

    /**
     * @param  list<array<string, int|string>>  $rows
     */
    private function fillEnrollmentList(string $sheet, array $rows, ChedReportHeader $header): string
    {
        $columns = [
            'A' => 'no', 'B' => 'program', 'C' => 'major', 'D' => 'student_number', 'E' => 'first_name',
            'F' => 'middle_name', 'G' => 'surname', 'H' => 'name_extension', 'I' => 'citizenship',
            'J' => 'gender', 'K' => 'year_level', 'L' => 'subjects', 'M' => 'units', 'N' => 'remarks',
        ];

        [$before, $rowsXml, $after] = $this->splitSheetData($sheet);
        $byNumber = $this->rowsByNumber($rowsXml);
        $first = 8;
        $kept = $this->rowsAbove($byNumber, $first);
        $generated = $this->dataRows($byNumber[$first], $first, $rows, $columns);

        $lastRow = $first + max(count($rows), 1) - 1;
        $sheet = $before.$kept.implode('', $generated).$after;
        $sheet = $this->setDimension($sheet, "A1:N{$lastRow}");
        $sheet = $this->tidyView($sheet);

        $sheet = $this->setText($sheet, 'B1', $header->schoolName);
        $sheet = $this->setText($sheet, 'B2', $header->schoolAddress);

        return $this->setText($sheet, 'B3', $header->termLabel);
    }

    /**
     * @param  list<array<string, int|string>>  $rows
     */
    private function fillNstpList(string $sheet, array $rows, ChedReportHeader $header): string
    {
        $columns = [
            'A' => 'no', 'B' => 'serial_no', 'C' => 'surname', 'D' => 'first_name', 'E' => 'middle_name',
            'F' => 'course', 'G' => 'gender', 'H' => 'birthdate', 'I' => 'street_barangay', 'J' => 'town_city',
            'K' => 'province', 'L' => 'contact_number', 'M' => 'email',
        ];

        [$before, $rowsXml, $after] = $this->splitSheetData($sheet);
        $byNumber = $this->rowsByNumber($rowsXml);
        $first = 14;
        $footerStart = $this->footerStart($byNumber, $first);
        $count = max(count($rows), 1);
        $delta = $count - ($footerStart - $first);

        $kept = $this->rowsAbove($byNumber, $first);
        $generated = $this->dataRows($byNumber[$first], $first, $rows, $columns);
        $lastData = $first + $count - 1;
        $genders = ['MALE' => 0, 'FEMALE' => 0];
        foreach ($rows as $row) {
            $word = (string) ($row['gender'] ?? '');
            if (isset($genders[$word])) {
                $genders[$word]++;
            }
        }

        $footer = '';
        $lastRow = $lastData;
        foreach ($byNumber as $number => $xml) {
            if ($number < $footerStart) {
                continue;
            }
            $footer .= $this->shiftRow($xml, $delta, $footerStart);
            $lastRow = max($lastRow, $number + $delta);
        }
        $footer = (string) preg_replace_callback(
            '#<f>COUNTIF\(G'.$first.':G\d+,"(MALE|FEMALE)"\)</f><v>[^<]*</v>#',
            static fn (array $m): string => "<f>COUNTIF(G{$first}:G{$lastData},\"{$m[1]}\")</f><v>{$genders[$m[1]]}</v>",
            $footer,
        );

        $sheet = $before.$kept.implode('', $generated).$footer.$after;
        $sheet = $this->shiftMerges($sheet, $footerStart, $delta);
        $sheet = $this->setDimension($sheet, "A2:M{$lastRow}");
        $sheet = $this->tidyView($sheet);
        $sheet = $this->widenNumberColumn($sheet, count($rows));

        $sheet = $this->setText($sheet, 'A7', "  {$header->semesterLabel} :    School Year :   {$header->schoolYear}");
        $sheet = $this->setText($sheet, 'C9', $header->schoolName);

        return $this->setText($sheet, 'C10', $header->schoolAddress);
    }

    // ---- rows -------------------------------------------------------------------------------

    /**
     * One new row per record, cloned from the template's first data row, or a single blank
     * (styled, unnumbered) row when there are no records.
     *
     * @param  list<array<string, int|string>>  $rows
     * @param  array<string, string>  $columns  column letter => row key
     * @return list<string>
     */
    private function dataRows(string $prototype, int $first, array $rows, array $columns): array
    {
        $numeric = ['no', 'year_level', 'units'];
        $generated = [];

        foreach (($rows === [] ? [null] : $rows) as $index => $row) {
            $values = [];
            foreach ($columns as $letter => $key) {
                $value = $row === null ? '' : ($row[$key] ?? '');
                $values[$letter] = in_array($key, $numeric, true) && is_numeric($value)
                    ? ['n', (string) $value]
                    : ['t', (string) $value];
            }
            $generated[] = $this->cloneRow($prototype, $first + $index, $values);
        }

        return $generated;
    }

    /**
     * @param  array<string, array{0: string, 1: string}>  $values  column letter => [kind, text]
     */
    private function cloneRow(string $prototype, int $number, array $values): string
    {
        if (preg_match('#^<row\b([^>]*?)/?>#', $prototype, $open) !== 1) {
            throw new RuntimeException('The template data row is not a row element.');
        }

        $attributes = (string) preg_replace('/\br="\d+"/', 'r="'.$number.'"', $open[1]);

        preg_match_all(self::CELL, $prototype, $cells, PREG_SET_ORDER);
        $out = '';
        foreach ($cells as $cell) {
            if (preg_match('/\br="([A-Z]+)\d+"/', $cell[1], $ref) !== 1) {
                throw new RuntimeException('A template data cell has no reference.');
            }

            preg_match('/\bs="(\d+)"/', $cell[1], $style);
            $letter = $ref[1];
            $s = isset($style[1]) ? ' s="'.$style[1].'"' : '';
            [$kind, $text] = $values[$letter] ?? ['t', ''];

            $out .= match (true) {
                $text === '' => '<c r="'.$letter.$number.'"'.$s.'/>',
                $kind === 'n' => '<c r="'.$letter.$number.'"'.$s.'><v>'.$text.'</v></c>',
                default => '<c r="'.$letter.$number.'"'.$s.' t="inlineStr"><is><t xml:space="preserve">'.$this->escape($text).'</t></is></c>',
            };
        }

        return '<row'.$attributes.'>'.$out.'</row>';
    }

    /**
     * @return array{0: string, 1: string, 2: string} everything before the rows, the rows, everything after
     */
    private function splitSheetData(string $sheet): array
    {
        if (preg_match('#^(.*?<sheetData>)(.*)(</sheetData>.*)$#s', $sheet, $m) !== 1) {
            throw new RuntimeException('The template worksheet has no sheetData.');
        }

        return [$m[1], $m[2], $m[3]];
    }

    /**
     * @return array<int, string> row number => row XML
     */
    private function rowsByNumber(string $rowsXml): array
    {
        preg_match_all(self::ROW, $rowsXml, $matches);
        $rows = [];
        foreach ($matches[0] as $xml) {
            if (preg_match('/\br="(\d+)"/', $xml, $number) !== 1) {
                throw new RuntimeException('A template row has no row number.');
            }

            $rows[(int) $number[1]] = $xml;
        }

        return $rows;
    }

    /**
     * @param  array<int, string>  $byNumber
     */
    private function rowsAbove(array $byNumber, int $first): string
    {
        if (! isset($byNumber[$first])) {
            throw new RuntimeException("The template has no row {$first} to copy the data rows from.");
        }

        return implode('', array_filter($byNumber, static fn (int $number): bool => $number < $first, ARRAY_FILTER_USE_KEY));
    }

    /**
     * The first row at or below the data that holds a COUNTIF: the "Sub Total" row.
     *
     * @param  array<int, string>  $byNumber
     */
    private function footerStart(array $byNumber, int $first): int
    {
        foreach ($byNumber as $number => $xml) {
            if ($number > $first && str_contains($xml, 'COUNTIF')) {
                return $number;
            }
        }

        throw new RuntimeException('The template has no footer to move.');
    }

    private function shiftRow(string $xml, int $delta, int $footerStart): string
    {
        return (string) preg_replace_callback(
            '/\br="([A-Z]*)(\d+)"/',
            static fn (array $m): string => 'r="'.$m[1].((int) $m[2] >= $footerStart ? (int) $m[2] + $delta : (int) $m[2]).'"',
            $xml,
        );
    }

    private function shiftMerges(string $sheet, int $footerStart, int $delta): string
    {
        return (string) preg_replace_callback(
            '#<mergeCell ref="([A-Z]+)(\d+):([A-Z]+)(\d+)"/>#',
            static fn (array $m): string => '<mergeCell ref="'.$m[1].((int) $m[2] >= $footerStart ? (int) $m[2] + $delta : $m[2])
                .':'.$m[3].((int) $m[4] >= $footerStart ? (int) $m[4] + $delta : $m[4]).'"/>',
            $sheet,
        );
    }

    // ---- cells ------------------------------------------------------------------------------

    private function setText(string $sheet, string $ref, string $text): string
    {
        return $this->replaceCell($sheet, $ref, fn (string $style): string => '<c r="'.$ref.'"'.$style.' t="inlineStr"><is><t xml:space="preserve">'.$this->escape($text).'</t></is></c>');
    }

    /**
     * @param  bool  $keepFormula  a TOTAL-row cell: change only the cached value, keep its formula
     */
    private function setNumber(string $sheet, string $ref, int $value, bool $keepFormula = false): string
    {
        if (! $keepFormula) {
            return $this->replaceCell($sheet, $ref, fn (string $style): string => '<c r="'.$ref.'"'.$style.'><v>'.$value.'</v></c>');
        }

        $count = 0;
        $out = (string) preg_replace_callback(
            '#(<c r="'.$ref.'"[^>]*>(?:<f[^>]*/>|<f[^>]*>[^<]*</f>))<v>[^<]*</v>#',
            static fn (array $m): string => $m[1].'<v>'.$value.'</v>',
            $sheet,
            1,
            $count,
        );

        if ($count !== 1) {
            throw new RuntimeException("The template has no formula cell {$ref}.");
        }

        return $out;
    }

    /**
     * @param  callable(string): string  $build  gets the cell's ` s="n"` attribute (or '')
     */
    private function replaceCell(string $sheet, string $ref, callable $build): string
    {
        $count = 0;
        $out = (string) preg_replace_callback(
            '#<c r="'.$ref.'"((?: s="\d+")?)(?: t="\w+")?(?:/>|>.*?</c>)#s',
            static fn (array $m): string => $build($m[1]),
            $sheet,
            1,
            $count,
        );

        if ($count !== 1) {
            throw new RuntimeException("The template has no cell {$ref}.");
        }

        return $out;
    }

    private function escape(string $text): string
    {
        $clean = (string) preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/', '', $text);

        return htmlspecialchars($clean, ENT_XML1 | ENT_QUOTES, 'UTF-8');
    }

    private function columnLetter(int $index): string
    {
        $letter = '';
        while ($index > 0) {
            $index--;
            $letter = chr(65 + $index % 26).$letter;
            $index = intdiv($index, 26);
        }

        return $letter;
    }

    // ---- sheet-level ------------------------------------------------------------------------

    private function setDimension(string $sheet, string $range): string
    {
        return (string) preg_replace('#<dimension ref="[^"]*"/>#', '<dimension ref="'.$range.'"/>', $sheet, 1);
    }

    /** The template was saved scrolled far down with a block selected: open it at the top. */
    private function tidyView(string $sheet): string
    {
        $sheet = (string) preg_replace('# topLeftCell="[^"]*"#', '', $sheet, 1);

        return (string) preg_replace('#<selection [^>]*/>#', '<selection activeCell="A1" sqref="A1"/>', $sheet, 1);
    }

    /** The No. column of the NSTP forms is 2.5 characters wide: too narrow for a number above 99. */
    private function widenNumberColumn(string $sheet, int $rowCount): string
    {
        $width = $rowCount >= 1000 ? '6.7109375' : ($rowCount >= 100 ? '5.7109375' : null);

        if ($width === null) {
            return $sheet;
        }

        return (string) preg_replace('#(<col min="1" max="1" width=")[0-9.]+(")#', '${1}'.$width.'${2}', $sheet, 1);
    }

    // ---- package ----------------------------------------------------------------------------

    private function openCopyOf(ChedReport $report, string $path): ZipArchive
    {
        $directory = $this->templateDirectory ?? resource_path('ched-templates');
        $template = $directory.DIRECTORY_SEPARATOR.self::TEMPLATES[$report->value];

        if (! is_file($template) || ! copy($template, $path)) {
            throw new RuntimeException("The {$report->value} template could not be copied.");
        }

        $zip = new ZipArchive;

        if ($zip->open($path) !== true) {
            throw new RuntimeException("The {$report->value} template is not a readable workbook.");
        }

        return $zip;
    }

    private function sheetOf(ZipArchive $zip): string
    {
        $sheet = $zip->getFromName(self::SHEET);

        if ($sheet === false) {
            throw new RuntimeException('The template workbook has no first worksheet.');
        }

        return $sheet;
    }

    private function save(ZipArchive $zip, string $sheet): void
    {
        $zip->addFromString(self::SHEET, $sheet, ZipArchive::FL_OVERWRITE);

        if ($zip->locateName('xl/calcChain.xml') !== false) {
            $zip->deleteName('xl/calcChain.xml');
            $this->patch($zip, '[Content_Types].xml', '#<Override PartName="/xl/calcChain\.xml"[^>]*/>#', '');
            $this->patch($zip, 'xl/_rels/workbook.xml.rels', '#<Relationship [^>]*Target="calcChain\.xml"[^>]*/>#', '');
        }

        if (preg_match('#<calcPr\b#', (string) $zip->getFromName('xl/workbook.xml')) === 1) {
            $this->patch($zip, 'xl/workbook.xml', '#<calcPr\b([^>]*?)\s*/>#', '<calcPr$1 fullCalcOnLoad="1"/>');
        }

        if (! $zip->close()) {
            throw new RuntimeException('The workbook could not be written.');
        }
    }

    private function patch(ZipArchive $zip, string $part, string $pattern, string $replacement): void
    {
        $xml = $zip->getFromName($part);

        if ($xml === false) {
            return;
        }

        $zip->addFromString($part, (string) preg_replace($pattern, $replacement, $xml), ZipArchive::FL_OVERWRITE);
    }
}
